#!/usr/bin/env python3
import os
import time
ROOT = "/workspace/notebooks/llama.cpp-ph2"
BASE = os.path.join(ROOT, "ggml/src/ggml-cuda8")
SMOKE_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend-graph-builder-add-smoke.cpp")
CMAKE = os.path.join(BASE, "CMakeLists.txt")
SMOKE_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend-graph-builder-add-smoke.cpp\n// G16A smoke: real GGML graph-builder ADD graph -> CUDA8 backend graph_compute.\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n#include "ggml.h"\n#include "ggml-impl.h"\n#include "ggml-backend.h"\n#include "ggml-backend-impl.h"\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n#include <stdint.h>\n#include <vector>\n\nstatic bool expect_resident(const char * label, const ggml_tensor * t, size_t bytes, ggml_backend_buffer_t expected, size_t expected_offset) {\n    ggml_backend_buffer_t owner = NULL;\n    size_t offset = 0;\n    if (!ggml_cuda8_ggml_tensor_is_device_resident(t, bytes, &owner, &offset)) {\n        std::fprintf(stderr, "%s: residency not found\\n", label);\n        return false;\n    }\n    if (owner != expected || offset != expected_offset) {\n        std::fprintf(stderr, "%s: residency mismatch offset=%zu expected=%zu\\n", label, offset, expected_offset);\n        return false;\n    }\n    std::printf("%s residency PASS offset=%zu\\n", label, offset);\n    return true;\n}\n\nstatic void force_1d_f32_data_layout(ggml_tensor * t, int64_t n, void * data) {\n    t->type = GGML_TYPE_F32;\n    t->ne[0] = n;\n    t->ne[1] = 1;\n    t->ne[2] = 1;\n    t->ne[3] = 1;\n    t->nb[0] = sizeof(float);\n    t->nb[1] = (size_t) n * sizeof(float);\n    t->nb[2] = t->nb[1];\n    t->nb[3] = t->nb[1];\n    t->data = data;\n}\n\nint main(int argc, char ** argv) {\n    (void) argc;\n    (void) argv;\n    std::printf("ggml-cuda8-ggml-backend-graph-builder-add-smoke: starting\\n");\n\n    const int n = 512;\n    const size_t bytes = (size_t) n * sizeof(float);\n\n    std::vector<uint8_t> ggml_mem(4 * 1024 * 1024);\n    struct ggml_init_params params;\n    std::memset(&params, 0, sizeof(params));\n    params.mem_size = ggml_mem.size();\n    params.mem_buffer = ggml_mem.data();\n    params.no_alloc = false;\n\n    ggml_context * gctx = ggml_init(params);\n    if (gctx == NULL) { std::fprintf(stderr, "ggml_init failed\\n"); return 1; }\n\n    ggml_tensor * a = ggml_new_tensor_1d(gctx, GGML_TYPE_F32, n);\n    ggml_tensor * b = ggml_new_tensor_1d(gctx, GGML_TYPE_F32, n);\n    ggml_tensor * c = ggml_add(gctx, a, b);\n    if (a == NULL || b == NULL || c == NULL) {\n        std::fprintf(stderr, "ggml graph tensor creation failed\\n");\n        ggml_free(gctx);\n        return 1;\n    }\n\n    ggml_cgraph * graph = ggml_new_graph(gctx);\n    if (graph == NULL) {\n        std::fprintf(stderr, "ggml_new_graph failed\\n");\n        ggml_free(gctx);\n        return 1;\n    }\n    ggml_build_forward_expand(graph, c);\n\n    std::printf("real ggml graph n_nodes=%d n_leafs=%d\\n", graph->n_nodes, graph->n_leafs);\n    for (int i = 0; i < graph->n_nodes; ++i) {\n        std::printf("real graph node %d op=%d\\n", i, graph->nodes[i] ? (int) graph->nodes[i]->op : -1);\n    }\n    if (graph->n_nodes < 1) {\n        std::fprintf(stderr, "real ggml graph unexpectedly has no nodes\\n");\n        ggml_free(gctx);\n        return 1;\n    }\n\n    ggml_backend_t backend = ggml_cuda8_ggml_backend_init(0);\n    if (backend == NULL) { std::fprintf(stderr, "backend init failed\\n"); ggml_free(gctx); return 1; }\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "backend identity check failed\\n");\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    if (backend->iface.graph_compute == NULL) {\n        std::fprintf(stderr, "backend graph_compute callback is NULL\\n");\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    std::printf("backend name: %s\\n", backend->iface.get_name(backend));\n\n    ggml_backend_buffer_type_t buft = ggml_cuda8_ggml_backend_get_default_buffer_type(backend);\n    if (buft == NULL) {\n        std::fprintf(stderr, "backend default buffer type is NULL\\n");\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    std::printf("backend default buffer type: %s\\n", buft->iface.get_name(buft));\n\n    const size_t off_a = 0;\n    const size_t off_b = 4096;\n    const size_t off_c = 8192;\n    const size_t total_size = 12288;\n\n    ggml_backend_buffer_t buffer = buft->iface.alloc_buffer(buft, total_size);\n    if (buffer == NULL) {\n        std::fprintf(stderr, "buffer alloc failed\\n");\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    void * base = buffer->iface.get_base(buffer);\n    if (base == NULL) {\n        std::fprintf(stderr, "buffer base is NULL\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    std::printf("backend-owned graph-builder buffer size: %zu\\n", buffer->size);\n    std::printf("buffer base:                         %p\\n", base);\n\n    uint8_t * base_u8 = (uint8_t *) base;\n    force_1d_f32_data_layout(a, n, base_u8 + off_a);\n    force_1d_f32_data_layout(b, n, base_u8 + off_b);\n    force_1d_f32_data_layout(c, n, base_u8 + off_c);\n\n    if (buffer->iface.init_tensor(buffer, a) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, b) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, c) != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "init_tensor failed\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    if (!expect_resident("A", a, bytes, buffer, off_a) ||\n        !expect_resident("B", b, bytes, buffer, off_b) ||\n        !expect_resident("C", c, bytes, buffer, off_c)) {\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n\n    std::vector<float> a_host(n), b_host(n), c_ref(n), c_out(n, 0.0f);\n    for (int i = 0; i < n; ++i) {\n        a_host[i] = ((float) ((i * 17 + 3) % 101) - 50.0f) * 0.03125f;\n        b_host[i] = ((float) ((i * 19 + 5) % 97) - 48.0f) * 0.015625f;\n        c_ref[i] = a_host[i] + b_host[i];\n    }\n\n    buffer->iface.clear(buffer, 0);\n    buffer->iface.set_tensor(buffer, a, &a_host[0], 0, bytes);\n    buffer->iface.set_tensor(buffer, b, &b_host[0], 0, bytes);\n\n    enum ggml_status status = backend->iface.graph_compute(backend, graph);\n    if (status != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "backend graph_compute returned %d\\n", (int) status);\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n\n    buffer->iface.get_tensor(buffer, c, &c_out[0], 0, bytes);\n    double max_abs_err = 0.0;\n    for (int i = 0; i < n; ++i) {\n        const double diff = (double) c_out[i] - (double) c_ref[i];\n        const double abs_err = diff < 0.0 ? -diff : diff;\n        if (abs_err > max_abs_err) max_abs_err = abs_err;\n    }\n    std::printf("real graph-builder ADD_F32 max_abs_err=%.9g\\n", max_abs_err);\n    if (max_abs_err > 1e-6) {\n        std::fprintf(stderr, "real graph-builder ADD_F32 verification FAIL\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        ggml_free(gctx);\n        return 1;\n    }\n    std::printf("real graph-builder ADD_F32 verification PASS\\n");\n\n    buffer->iface.free_buffer(buffer);\n    backend->iface.free(backend);\n    ggml_free(gctx);\n    std::printf("ggml-cuda8-ggml-backend-graph-builder-add-smoke: SUCCESS\\n");\n    return 0;\n}\n'
CMAKE_TARGET = '\n# ---------------------------------------------------------------------------\n# G16A real GGML graph-builder ADD graph -> backend->iface.graph_compute smoke\n# ---------------------------------------------------------------------------\n\ncuda_add_executable(ggml-cuda8-ggml-backend-graph-builder-add-smoke\n    ggml-cuda8-ggml-backend-graph-builder-add-smoke.cpp\n)\n\ntarget_link_libraries(ggml-cuda8-ggml-backend-graph-builder-add-smoke\n    ggml-cuda8-kernels\n    ggml\n    ${CUDA_LIBRARIES}\n)\n'

def backup(path):
    if os.path.exists(path):
        b = path + ".g16a-backup-" + str(int(time.time()))
        with open(path, "r") as f:
            data = f.read()
        with open(b, "w") as f:
            f.write(data)
        print("backup", b)

def read_file(path):
    with open(path, "r") as f:
        return f.read()

def write_file(path, data):
    with open(path, "w") as f:
        f.write(data)

backup(SMOKE_CPP)
write_file(SMOKE_CPP, SMOKE_TEXT)
print("wrote", SMOKE_CPP)
backup(CMAKE)
cm = read_file(CMAKE)
if "ggml-cuda8-ggml-backend-graph-builder-add-smoke" not in cm:
    if not cm.endswith("\n"):
        cm += "\n"
    cm += CMAKE_TARGET
    write_file(CMAKE, cm)
    print("patched", CMAKE)
else:
    print("CMake target already present")
print("")
print("G16A writer complete.")
